        // Lava does not morph.
        let mut w = world();
        let i = w.index(30, 6);
        w.tiles[i].liquid = 200;
        w.tiles[i].set_liquid_kind(tr_core::tile::LiquidKind::Lava);
        let (mut pool, slot) = spawn(FLAMING_MACE, 480.0, 100.0);
        let ins = inputs(None, true, (480.0, 100.0), (480.0, 100.0));
        tick(&mut w, &mut pool, ins);
