        assert!(idx.is_some(), "the 1130 dash spawned");
        let idx = idx.unwrap();
        let dash = &pool.slots()[idx];
        assert_eq!(dash.damage, 40);
        // The 14-tile initial speed has decayed by the fade by the time the
